        {
          "n": 424,
          "name": "Vishrama",
          "en": "Provides rest for those who are tired of life."
        },
        {
          "n": 425,
          "name": "ViswaDakshina",
          "en": "An expert in all things or He who is more powerful than all others."
        },
        {
          "n": 426,
          "name": "Visthara",
          "en": "Makes all the world broaden in Him."
        }
