        {
          "n": 846,
          "name": "Vamsa Vardhana",
          "en": "Makes dynasties grow."
        },
        {
          "n": 847,
          "name": "Bhara Brit",
          "en": "Carries heavy worlds."
        },
        {
          "n": 848,
          "name": "Khadhitha",
          "en": "Called as ultimate truth by the Vedas."
        }
